import{_ as h,C as i,o as b,c as f,j as e,a as r,E as a,w as l,a2 as n}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"兔不能做的几件事","description":"兔的四个关键生理特性：不能呕吐、不能禁食、不能随便用抗生素、通过尿液排钙。理解这些，才能避免很多致命事故。","frontmatter":{"title":"兔不能做的几件事","description":"兔的四个关键生理特性：不能呕吐、不能禁食、不能随便用抗生素、通过尿液排钙。理解这些，才能避免很多致命事故。","lastReviewed":"2026-07-27T00:00:00.000Z"},"headers":[],"relativePath":"digest/key-traits.md","filePath":"digest/key-traits.md","lastUpdated":null}'),m={name:"digest/key-traits.md"};function _(p,t,c,q,T,P){const s=i("Danger"),u=i("Warning"),d=i("Info"),o=i("SourceCard"),g=i("SourceList");return b(),f("div",null,[t[10]||(t[10]=e("h1",{id:"🚫-兔不能做的几件事",tabindex:"-1"},[r("🚫 兔不能做的几件事 "),e("a",{class:"header-anchor",href:"#🚫-兔不能做的几件事","aria-label":'Permalink to "🚫 兔不能做的几件事"'},"​")],-1)),t[11]||(t[11]=e("p",null,[r("兔的生理与猫狗差异巨大。把猫狗的常识套用到兔身上，是很多致命事故的根源。本节讲"),e("strong",null,"四个最关键的生理特性"),r("。")],-1)),t[12]||(t[12]=e("h2",{id:"一、兔不能呕吐",tabindex:"-1"},[r("一、兔不能呕吐 "),e("a",{class:"header-anchor",href:"#一、兔不能呕吐","aria-label":'Permalink to "一、兔不能呕吐"'},"​")],-1)),a(s,{title:"这意味着误食异物和毛球极其危险"},{default:l(()=>[...t[0]||(t[0]=[r(" 猫能吐毛球，**兔不能**。任何阻碍食糜通过的情况，都会导致胃迅速被液体和气体扩张 → 危及生命的**胃扩张**。 ",-1)])]),_:1}),t[13]||(t[13]=n('<h3 id="为什么兔不能呕吐-解剖学原因" tabindex="-1">为什么兔不能呕吐（解剖学原因） <a class="header-anchor" href="#为什么兔不能呕吐-解剖学原因" aria-label="Permalink to &quot;为什么兔不能呕吐（解剖学原因）&quot;">​</a></h3><p>兽医学教科书对此有明确解释<cite><a href="#ref1">[1]</a></cite>：</p><ol><li><strong>强有力的胃食管括约肌（贲门）</strong>——作为单向阀门，阻止胃内容物反流</li><li><strong>食道平滑肌无法进行逆蠕动</strong>——只能向胃方向单向推进</li><li><strong>膈肌脚环绕食管裂孔形成 &quot;crural sling&quot;</strong>——额外的物理屏障</li><li>缺乏有效的呕吐反射神经环路</li></ol><h3 id="三个直接的饲养含义" tabindex="-1">三个直接的饲养含义 <a class="header-anchor" href="#三个直接的饲养含义" aria-label="Permalink to &quot;三个直接的饲养含义&quot;">​</a></h3><ol><li><strong>绝对禁止催吐</strong>——兔中毒后<strong>绝不能像狗那样催吐</strong>，既无效又危险（会导致误吸/窒息）</li><li><strong>毛球是结果而非原因</strong>——这是养兔界最大的误区之一。详见<a href="./../emergencies/hairball">毛球症急症</a></li><li><strong>误食异物极危险</strong>——兔无法通过呕吐排出，常需手术</li></ol><h2 id="二、兔不能禁食" tabindex="-1">二、兔不能禁食 <a class="header-anchor" href="#二、兔不能禁食" aria-label="Permalink to &quot;二、兔不能禁食&quot;">​</a></h2>',6)),a(s,{title:"禁食 ≥ 12 小时即视为急症"},{default:l(()=>[...t[1]||(t[1]=[r(" 兔兔**停止进食或排便 12 小时或更久 = EMERGENCY**，必须立即就医。**禁食 ≥ 24 小时**可发展为**肝脂质沉积症（hepatic lipidosis，脂肪肝）**、严重代谢性酸中毒、肝衰竭，可致死",-1),e("cite",null,[e("a",{href:"#ref2"},"[2]")],-1),e("cite",null,[e("a",{href:"#ref1"},"[1]")],-1),r("。 ",-1)])]),_:1}),t[14]||(t[14]=n('<h3 id="为什么兔不能像猫狗那样术前禁食" tabindex="-1">为什么兔不能像猫狗那样术前禁食 <a class="header-anchor" href="#为什么兔不能像猫狗那样术前禁食" aria-label="Permalink to &quot;为什么兔不能像猫狗那样术前禁食&quot;">​</a></h3><p>猫狗术前通常需禁食 8–12 小时以防麻醉时呕吐误吸。<strong>兔绝不能这样处理</strong>：</p><ul><li>兔不能呕吐 → 麻醉时<strong>本来就没有呕吐误吸风险</strong></li><li>兔胃&quot;几乎永不排空&quot; → 短时间禁食也无法真正清空胃</li><li>长时间禁食 → 触发 GI Stasis 恶性循环 → 麻醉风险反而上升</li></ul><p><strong>正确的围手术期管理</strong>：兔在术前、术中、术后都应<strong>尽快恢复进食</strong>，由熟悉兔科的异宠兽医制定方案<cite><a href="#ref1">[1]</a></cite>。</p><h3 id="饲养含义" tabindex="-1">饲养含义 <a class="header-anchor" href="#饲养含义" aria-label="Permalink to &quot;饲养含义&quot;">​</a></h3><ul><li>&quot;兔 12 小时不吃 = 急症&quot;是养兔人必须牢记的<strong>红线</strong></li><li>任何怀疑兔兔拒食（哪怕看起来还精神），都应<strong>立即联系异宠兽医</strong>，不要观望</li></ul><h2 id="三、兔不能随便用抗生素" tabindex="-1">三、兔不能随便用抗生素 <a class="header-anchor" href="#三、兔不能随便用抗生素" aria-label="Permalink to &quot;三、兔不能随便用抗生素&quot;">​</a></h2>',7)),a(u,{title:"某些常见抗生素对兔致命"},{default:l(()=>[...t[2]||(t[2]=[r(" **口服青霉素及衍生物**（如阿莫西林 Amoxicillin）、**头孢类**、**林可霉素/克林霉素**等可破坏兔盲肠菌群，引发致命的**抗生素相关性肠毒血症**（由 *Clostridium spiroforme* 产 iota 毒素引起）",-1),e("cite",null,[e("a",{href:"#ref1"},"[1]")],-1),r("。 ",-1)])]),_:1}),t[15]||(t[15]=n('<h3 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h3><p>兔的盲肠是一个由 74+ 种厌氧菌构成的精密平衡生态系统，正常菌群通过<strong>竞争性排斥</strong>抑制致病菌。某些抗生素（尤其是口服、广谱、抗厌氧菌的）会破坏这套平衡，让致命梭菌爆发<cite><a href="#ref1">[1]</a></cite>。</p><h3 id="饲养含义-1" tabindex="-1">饲养含义 <a class="header-anchor" href="#饲养含义-1" aria-label="Permalink to &quot;饲养含义&quot;">​</a></h3><ul><li><strong>任何对兔使用抗生素都必须由熟悉兔科的兽医开具</strong></li><li><strong>绝不要自行给兔用人用药或猫狗药</strong></li><li>优先选择对兔盲肠菌群影响小的药物（如恩诺沙星、甲硝唑、复方磺胺等）——具体方案必须由兽医决定</li><li>不要觉得&quot;上次剩的消炎药&quot;就能用——剂量和种类对兔极其敏感</li></ul><h2 id="四、兔通过尿液排钙" tabindex="-1">四、兔通过尿液排钙 <a class="header-anchor" href="#四、兔通过尿液排钙" aria-label="Permalink to &quot;四、兔通过尿液排钙&quot;">​</a></h2>',5)),a(d,{title:"兔的钙代谢独一无二"},{default:l(()=>[...t[3]||(t[3]=[r(" 与大多数哺乳动物（按需吸收、激素精细调节）不同，**兔的肠道钙吸收几乎与摄入量成正比**——吃多少吸多少。多余的钙**主要经尿液排出**",-1),e("cite",null,[e("a",{href:"#ref5"},"[5]")],-1),e("cite",null,[e("a",{href:"#ref6"},"[6]")],-1),r("。 ",-1)])]),_:1}),t[16]||(t[16]=n('<h3 id="这意味着什么" tabindex="-1">这意味着什么 <a class="header-anchor" href="#这意味着什么" aria-label="Permalink to &quot;这意味着什么&quot;">​</a></h3><ul><li>兔尿呈<strong>碱性</strong>，钙与碳酸根结合形成<strong>碳酸钙结晶</strong></li><li>高钙饮食时，尿钙排泄增加 → 尿液钙浓度升高 → 易形成结晶</li><li>沉淀为&quot;<strong>膀胱泥沙（sludge）</strong>&quot;，或聚结成<strong>尿结石（uroliths）</strong><cite><a href="#ref7">[7]</a></cite></li></ul><h3 id="高钙食物-成兔需控制频率和量" tabindex="-1">高钙食物（成兔需控制频率和量） <a class="header-anchor" href="#高钙食物-成兔需控制频率和量" aria-label="Permalink to &quot;高钙食物（成兔需控制频率和量）&quot;">​</a></h3><ul><li><strong>苜蓿草</strong>、苜蓿颗粒（这是为什么苜蓿只给幼兔/孕兔，成兔要避免）</li><li>高钙绿叶：<strong>羽衣甘蓝（kale）、菠菜（spinach）、蒲公英叶、欧芹</strong>、瑞士甜菜、菊苣</li></ul><h3 id="饲养含义-2" tabindex="-1">饲养含义 <a class="header-anchor" href="#饲养含义-2" aria-label="Permalink to &quot;饲养含义&quot;">​</a></h3><ol><li><strong>成兔以提摩西草为主</strong>（&gt;80%），低钙</li><li><strong>限制高钙蔬菜</strong>的频率和量</li><li><strong>鼓励大量饮水</strong>（多个水碗、新鲜含水蔬菜）——这是预防膀胱泥沙最实际的办法</li><li>出现<strong>尿钙</strong>（尿液浑浊、有白色沙粒残留）应及时咨询兽医</li><li><strong>不要给成兔额外补钙</strong>或含钙的营养补充剂</li></ol>',6)),a(d,{title:"个体差异"},{default:l(()=>[...t[4]||(t[4]=[r(' Oxbow 指出：有些长期高钙饮食的兔从不发病，有些正常/低钙饮食的兔也会发病——**遗传和水合状态也起作用**。所以"低钙饮食"是降低风险，不是绝对保证',-1),e("cite",null,[e("a",{href:"#ref7"},"[7]")],-1),r("。 ",-1)])]),_:1}),t[17]||(t[17]=n('<h2 id="五、总结-兔的-四不一控" tabindex="-1">五、总结：兔的&quot;四不一控&quot; <a class="header-anchor" href="#五、总结-兔的-四不一控" aria-label="Permalink to &quot;五、总结：兔的&quot;四不一控&quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th>不能</th><th>原因</th><th>实操</th></tr></thead><tbody><tr><td><strong>不能呕吐</strong></td><td>强贲门括约肌 + 食道不可逆蠕动</td><td>中毒<strong>禁止催吐</strong>；毛球是结果非原因</td></tr><tr><td><strong>不能禁食</strong></td><td>胃几乎永不排空，禁食触发恶性循环</td><td><strong>12 小时不吃 = 急症</strong>；术前不禁食</td></tr><tr><td><strong>不能乱用抗生素</strong></td><td>破坏盲肠菌群 → 致命肠毒血症</td><td>一切抗生素<strong>必须异宠兽医开具</strong></td></tr><tr><td><strong>不能像猫狗养</strong></td><td>后肠发酵、严格草食、钙代谢独特</td><td>牧草为主，控制颗粒粮和高钙食物</td></tr><tr><td><strong>控钙</strong></td><td>多余钙经尿排出 → 膀胱泥沙/结石</td><td>成兔以提摩西为主，限制高钙蔬菜</td></tr></tbody></table>',2)),a(g,null,{default:l(()=>[t[5]||(t[5]=e("p",null,[e("a",{id:"ref1"})],-1)),a(o,{title:"Gastrointestinal Diseases of Rabbits",author:"Oglesbee BL & Lord B (2020), Ferrets, Rabbits, and Rodents",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC7258705/",accessed:"2026-07-27",level:"vet",note:"兔无法呕吐的权威陈述；毛球是结果非原因；抗生素相关肠毒血症机制；围手术期不禁食；肝脂质沉积症。"}),t[6]||(t[6]=e("p",null,[e("a",{id:"ref2"})],-1)),a(o,{title:"GI Stasis: The Silent Killer",author:"Dana Krempels, House Rabbit Society",url:"https://rabbit.org/care/gi-stasis/",accessed:"2026-07-27",level:"vet",note:"12 小时不吃不拉 = EMERGENCY 的明确表述。"}),t[7]||(t[7]=e("p",null,[e("a",{id:"ref5"})],-1)),a(o,{title:"Rabbit calcium metabolism, 'bladder sludge,' and urolithiasis (Proceedings)",author:"DVM360（兽医会议论文）",url:"https://www.dvm360.com/view/rabbit-calcium-metabolism-bladder-sludge-and-urolithiasis-proceedings",accessed:"2026-07-27",level:"vet",note:"兔按摄入比例吸收钙、经尿排出的机制详解。"}),t[8]||(t[8]=e("p",null,[e("a",{id:"ref6"})],-1)),a(o,{title:"Influence of diet on calcium metabolism…",author:"Clauss M et al. (2012), J Anim Physiol Anim Nutr",url:"https://pubmed.ncbi.nlm.nih.gov/21707782/",accessed:"2026-07-27",level:"vet",note:"兔钙代谢的同行评审研究，PubMed 收录。"}),t[9]||(t[9]=e("p",null,[e("a",{id:"ref7"})],-1)),a(o,{title:"Bladder Sludge and Bladder Stones in Rabbits and Guinea Pigs",author:"VCA Animal Hospitals (Gregory Rich, DVM)",url:"https://vcahospitals.com/know-your-pet/bladder-sludge-and-bladder-stones-in-rabbits-and-guinea-pigs",accessed:"2026-07-27",level:"vet",note:"膀胱泥沙/结石的临床表现与高钙饮食关联。经 WebFetch 实际访问核实。"})]),_:1})])}const x=h(m,[["render",_]]);export{k as __pageData,x as default};
